# ── 本腳本自己的小工具（不是 wizard 函式庫）────────────────────────────────

die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
lower() { printf '%s' "$1" | tr '[:upper:]' '[:lower:]'; }
same() { [[ "$(lower "$1")" == "$(lower "$2")" ]]; }

# load KEY — 把 env 檔裡已存的值讀進變數（重跑時用）。
load() { local v; v=$(_existing "$1" || true); printf -v "$1" '%s' "$v"; }
for k in ACCOUNT GUARDIAN HEROES_RPC_URL PY EXCHANGE_NEW COPYTRACKER_NEW STRATEGY_REGISTRY_NEW SESSION_MANAGER_NEW \
         TRADER_STAKE ORACLE_NEW VERIFIED_130 PLATFORM_FEE_SPLITTER CARBON_RETIREMENT INSURANCE_VAULT_NEW FEE_ROUTER_NEW \
         COPYTRACKER_FINAL FOLLOWUPS_SENT PEPE_INCENTIVES ESG_REWARD_DISTRIBUTOR REPLAY_DONE ANALYTICS_DONE ORACLE_HANDED_OVER; do
  load "$k"
done

# done_already KEY — 這一步已經完成（env 檔有值）就說一聲，回傳成功讓呼叫端跳過。
done_already() {
  if [[ -n "${!1:-}" ]]; then
    ok "已完成（$1=${!1}），跳過。要重做請先從 $ENV_FILE 刪掉這一行"
    pause
    return 0
  fi
  return 1
}

# run LOG cmd... — 執行並把輸出同時存檔；失敗就停。
run() {
  local log="$LOGS/$1"; shift
  note "\$ $*"
  "$@" 2>&1 | tee "$log" || die "失敗，完整輸出在 $log。修正後重跑本腳本（已完成的步驟會跳過）"
}

# grab LABEL LOG — 從 forge 輸出抓「LABEL = 0x…」或「LABEL: 0x…」。
grab() {
  grep -aoE "$1[[:space:]]*[=:][[:space:]]*0x[0-9a-fA-F]{40}" "$LOGS/$2" | tail -n1 | grep -oE '0x[0-9a-fA-F]{40}' || true
}

call() { cast call "$@" --rpc-url "$RPC" | head -n1 | awk '{print $1}'; }

# forge_broadcast LOG SCRIPT — 用部署者 keystore 廣播（環境變數由呼叫端 export）。
forge_broadcast() {
  local log="$1" script="$2"
  (cd contracts && forge script "script/$script" --rpc-url "$RPC" \
    --account "$ACCOUNT" --sender "$DEPLOYER" --broadcast --slow -vv) 2>&1 | tee "$LOGS/$log"
}

