  export EXCHANGE=$EXCHANGE_NEW STRATEGY_REGISTRY=$STRATEGY_REGISTRY_NEW TRADER_STAKE TREASURY=$DEPLOYER \
    CARBON_SPLITTER=$PLATFORM_FEE_SPLITTER KEEP_DEPLOYER_OWNER=true
  forge_broadcast 4-insurance.log RedeployInsuranceStack.s.sol:RedeployInsuranceStack \
    || die "部署失敗，見 $LOGS/4-insurance.log（續跑用 RESUME_VAULT、RESUME_FEE_ROUTER、RESUME_COPY_TRACKER）"
  INSURANCE_VAULT_NEW=$(grab InsuranceVault_NEW 4-insurance.log)
  FEE_ROUTER_NEW=$(grab FeeRouter_NEW 4-insurance.log)
  v=$(grab CopyTracker_NEW 4-insurance.log)
  [[ -n "$INSURANCE_VAULT_NEW" && -n "$FEE_ROUTER_NEW" && -n "$v" ]] || die "輸出裡找不到新合約位址"
  write_env INSURANCE_VAULT_NEW "$INSURANCE_VAULT_NEW"
  write_env FEE_ROUTER_NEW "$FEE_ROUTER_NEW"
  COPYTRACKER_FINAL=$v
  write_env COPYTRACKER_FINAL "$v"
  pause
fi

# ── 8 ────────────────────────────────────────────────────────────────────
stage "送出四筆後續呼叫（交易所與 TraderStake 改接新合約）"
if ! done_already FOLLOWUPS_SENT; then
  mapfile -t TARGETS < <(grep -aoE 'target:[[:space:]]*0x[0-9a-fA-F]{40}' "$LOGS/4-insurance.log" | grep -oE '0x[0-9a-fA-F]{40}')
  mapfile -t PAYLOADS < <(grep -aA1 'payload:' "$LOGS/4-insurance.log" | grep -aoE '^[[:space:]]*0x[0-9a-fA-F]+' | tr -d ' ')
  (( ${#TARGETS[@]} == 4 && ${#PAYLOADS[@]} == 4 )) \
    || die "從 $LOGS/4-insurance.log 讀到 ${#TARGETS[@]} 個 target、${#PAYLOADS[@]} 個 payload，應各 4 個"
  for i in 0 1 2 3; do say "[$i] ${TARGETS[$i]}  ${PAYLOADS[$i]:0:10}…"; done
  warn "四筆要連續送完，中間不要做別的（否則交易所與 TraderStake 的 CopyTracker 不一致）。"
  confirm "送出？" || die "沒有送出"
  for i in 0 1 2 3; do
    run "5-followup-$i.log" cast send "${TARGETS[$i]}" "${PAYLOADS[$i]}" --rpc-url "$RPC" --account "$ACCOUNT"
  done
  fail=""
  same "$(call "$EXCHANGE_NEW" 'insuranceVault()(address)')" "$INSURANCE_VAULT_NEW" || fail+=" exchange.insuranceVault"
  same "$(call "$EXCHANGE_NEW" 'feeRouter()(address)')" "$FEE_ROUTER_NEW" || fail+=" exchange.feeRouter"
  same "$(call "$EXCHANGE_NEW" 'copyTracker()(address)')" "$COPYTRACKER_FINAL" || fail+=" exchange.copyTracker"
  same "$(call "$TRADER_STAKE" 'copyTracker()(address)')" "$COPYTRACKER_FINAL" || fail+=" TraderStake.copyTracker"
  same "$(call "$FEE_ROUTER_NEW" 'platformTreasury()(address)')" "$PLATFORM_FEE_SPLITTER" || fail+=" FeeRouter.platformTreasury"
  [[ -z "$fail" ]] || die "讀回不符：$fail"
  ok "讀回：交易所接新金庫、新 FeeRouter、最終 CopyTracker；平台份額付給分流合約"
  write_env FOLLOWUPS_SENT "yes"
  pause
fi

# ── 9 ────────────────────────────────────────────────────────────────────
stage "PepeIncentives＋EsgRewardDistributor（綁新交易所）"
if [[ -z "$PEPE_INCENTIVES" ]]; then
  confirm "部署 PepeIncentives？" || die "沒有部署"
  export PEPE_TOKEN PERPETUAL_EXCHANGE=$EXCHANGE_NEW COPY_TRACKER=$COPYTRACKER_FINAL ESG_REGISTRY=$ZERO
  forge_broadcast 6-pepe.log DeployPepeIncentives.s.sol:DeployPepeIncentives || die "部署失敗，見 $LOGS/6-pepe.log"
  PEPE_INCENTIVES=$(grab "PepeIncentives deployed" 6-pepe.log)
  [[ -n "$PEPE_INCENTIVES" ]] || die "找不到 PepeIncentives 位址"
  write_env PEPE_INCENTIVES "$PEPE_INCENTIVES"
else
  ok "PepeIncentives 已部署（$PEPE_INCENTIVES）"
fi
if [[ -z "$ESG_REWARD_DISTRIBUTOR" ]]; then
  confirm "部署 EsgRewardDistributor？" || die "沒有部署"
  export EXCHANGE_NEW ESG_REGISTRY_V2=$ESG_V2 SUSTAINABILITY_BADGE=$BADGE
  forge_broadcast 7-esg.log Deploy102RewardDistributor.s.sol:Deploy102RewardDistributor || die "部署失敗，見 $LOGS/7-esg.log"
  ESG_REWARD_DISTRIBUTOR=$(grab EsgRewardDistributor 7-esg.log)
  [[ -n "$ESG_REWARD_DISTRIBUTOR" ]] || die "找不到 EsgRewardDistributor 位址"
  write_env ESG_REWARD_DISTRIBUTOR "$ESG_REWARD_DISTRIBUTOR"
else
  ok "EsgRewardDistributor 已部署（$ESG_REWARD_DISTRIBUTOR）"
fi
same "$(call "$PEPE_INCENTIVES" 'exchange()(address)')" "$EXCHANGE_NEW" || die "PepeIncentives 沒綁新交易所"
same "$(call "$ESG_REWARD_DISTRIBUTOR" 'exchange()(address)')" "$EXCHANGE_NEW" || die "EsgRewardDistributor 沒綁新交易所"
ok "兩個合約都綁新交易所"
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "回放（公開鏈模式，約 2–3 小時；中斷就重跑本腳本，從最後完成的那一天接著跑）"
if ! done_already REPLAY_DONE; then
  if [[ -f heroes/out/progress-84532.json ]]; then
    ok "已有進度檔：接著上次的回放（排程不重新產生，否則會與進度不符）"
  else
    say "先把價格與排程推到最新收盤日。"
    if confirm "更新價格並重新產生排程？（第一次回放前要做）"; then
      run 8-prices.log bash -c "cd heroes && '$PYABS' fetch_prices.py && '$PYABS' build_schedule.py"
    fi
    [[ -f heroes/out/schedule.json ]] || die "沒有 heroes/out/schedule.json"
  fi
  run 9-addresses.log bash -c "cd agent && HEROES_RPC_URL='$HEROES_RPC_URL' npx tsx heroes/chainAddresses.ts '$EXCHANGE_NEW' ../heroes/out/addresses-84532.json"
  say "replay.ts 會問：部署者 keystore 密碼、這次回放帳號金鑰檔的密碼（第一次是新設，要記住），最後要輸入 replay on 84532。"
  warn "heroes/keys/84532.json 與它的密碼要保存到不再需要這些帳號為止。"
  pause "準備好就按 Enter 開始回放"
  (cd agent && HEROES_RPC_URL="$HEROES_RPC_URL" npx tsx heroes/replay.ts --public-chain \
    ../heroes/out/schedule.json ../heroes/out/addresses-84532.json ../heroes/out/events-84532.json \
    --progress ../heroes/out/progress-84532.json --keystore ../heroes/keys/84532.json --deployer-account "$ACCOUNT") \
    2>&1 | tee -a "$LOGS/10-replay.log" || die "回放停了（原因在上面）。處理完重跑本腳本，會從最後完成的那一天接著跑"
  write_env REPLAY_DONE "yes"
  pause
fi

# ── 11 ───────────────────────────────────────────────────────────────────
stage "績效分析＋對帳（產生 frontend/public/data/heroes/84532/）"
if ! done_already ANALYTICS_DONE; then
  run 11-analytics.log bash -c "cd heroes && '$PYABS' build_analytics.py out/events-84532.json && '$PYABS' check_pipeline.py out/events-84532.json out/schedule.json"
  write_env ANALYTICS_DONE "yes"
  pause
fi

# ── 12 ───────────────────────────────────────────────────────────────────
stage "新 MockOracle 交給 keeper"
if ! done_already ORACLE_HANDED_OVER; then
  say "回放已結束，之後由 keeper 寫現價。轉移後部署者不能再寫這顆 oracle。"
  confirm "transferOwnership($ORACLE_NEW → keeper $KEEPER)？" || die "沒有轉移"
  run 12-oracle.log cast send "$ORACLE_NEW" "transferOwnership(address)" "$KEEPER" --rpc-url "$RPC" --account "$ACCOUNT"
  same "$(call "$ORACLE_NEW" 'owner()(address)')" "$KEEPER" || die "讀回的 owner 不是 keeper"
  ok "新 MockOracle 的 owner 是 keeper"
  write_env ORACLE_HANDED_OVER "yes"
  pause
fi

finish
say "鏈上部分完成。新位址都在 $ENV_FILE（裡面也有 RPC 網址：不要提交或分享這個檔）。"
say "下一步交給 Claude 開 PR（addresses.ts、ABI、keeper／admin／oracle-health workflow 與 sha 釘選、"
say "monitoring、84532 資料集、broadcast 紀錄），合併後 Vercel 重新部署，再做公開站驗證。"
say "給 Claude 的位址（不含 RPC 網址）："
grep -vE '^(HEROES_RPC_URL|PY|ACCOUNT)=' "$ENV_FILE" | sed 's/^/    /'
printf '\n'
